-- BrandDesk > Brand kit > Social kit for Vegans Explore (Sean, 2026-11-15: "copy the logo... all the things that I would need in order
-- to update the page on its edit profile"): each platform's name, handle, bio within its limit, a tracked bio link and its files at exact size
-- (public/brand-kit/social/, rendered from /mocks/brand-kit/social). X, Threads and LinkedIn are not linked from the site yet. Safe to run twice.
update ve_brand_cartridges set data = jsonb_set(data, '{social}', '{"summary": "Everything to set up or refresh a Vegans Explore profile: the name, handle, bio sized for each platform, a tracked link, and the profile picture and header at each platform''s exact size.", "profiles": [{"platform": "Instagram", "handle": "@vegansexplore", "url": "https://www.instagram.com/vegansexplore/", "name": "Vegans Explore", "category": "Community", "bio": "Everything Vegan, near you. Restaurants, events, Guides and the Vegans Explore Podcast, city by city. Join free:", "limit": 150, "link": "https://vegansexplore.com/go/ve-bio-instagram", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}]}, {"platform": "TikTok", "handle": "@vegansexplore", "url": "https://www.tiktok.com/@vegansexplore", "name": "Vegans Explore", "bio": "Everything Vegan, near you. Places, events, Guides and our podcast.", "limit": 80, "link": "https://vegansexplore.com/go/ve-bio-tiktok", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}]}, {"platform": "Facebook", "handle": "vegansexplore", "url": "https://www.facebook.com/vegansexplore", "name": "Vegans Explore", "category": "Community", "bio": "Everything Vegan, near you: restaurants, events, Guides and the Vegans Explore Podcast.", "limit": 101, "link": "https://vegansexplore.com/go/ve-bio-facebook", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}, {"label": "Cover photo", "size": "1640 x 624", "url": "https://vegansexplore.com/public/brand-kit/social/facebook-cover.jpg"}]}, {"platform": "YouTube", "handle": "@VegansExplore", "url": "https://www.youtube.com/@VegansExplore", "name": "Vegans Explore", "bio": "Vegans Explore is everything Vegan, near you. Here you will find the Vegans Explore Podcast, our Guides and the people, places and events that make Vegan life easier, city by city. Find restaurants, events and Guides near you, and join free, at vegansexplore.com.", "limit": 1000, "link": "https://vegansexplore.com/go/ve-bio-youtube", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}, {"label": "Channel banner", "size": "2560 x 1440", "url": "https://vegansexplore.com/public/brand-kit/social/youtube-header.jpg"}]}, {"platform": "X", "handle": "@vegansexplore", "url": "", "name": "Vegans Explore", "bio": "Everything Vegan, near you. Restaurants, events, Guides and the Vegans Explore Podcast, city by city.", "limit": 160, "link": "https://vegansexplore.com/go/ve-bio-x", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}, {"label": "Header", "size": "1500 x 500", "url": "https://vegansexplore.com/public/brand-kit/social/x-header.jpg"}], "note": "Not linked from the site yet. If the account is new, claim this handle."}, {"platform": "Threads", "handle": "@vegansexplore", "url": "", "name": "Vegans Explore", "bio": "Everything Vegan, near you. Restaurants, events, Guides and the Vegans Explore Podcast, city by city.", "limit": 150, "link": "https://vegansexplore.com/go/ve-bio-threads", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}], "note": "Not linked from the site yet. If the account is new, claim this handle."}, {"platform": "LinkedIn", "handle": "vegans-explore", "url": "", "name": "Vegans Explore", "category": "Online Media", "bio": "Everything Vegan, near you: a directory, events, Guides and the Vegans Explore Podcast.", "limit": 120, "link": "https://vegansexplore.com/go/ve-bio-linkedin", "about": "Vegans Explore helps people find everything Vegan near them: restaurants and businesses, events, Guides and the Vegans Explore Podcast, city by city. Membership is free. Businesses claim their listing free and reach the people looking for them.", "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}, {"label": "Page banner", "size": "1584 x 396", "url": "https://vegansexplore.com/public/brand-kit/social/linkedin-banner.jpg"}], "note": "Not linked from the site yet. If the account is new, claim this handle."}], "files": [{"label": "Profile picture", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.png"}, {"label": "Profile picture (JPEG)", "size": "1080 x 1080", "url": "https://vegansexplore.com/public/brand-kit/social/profile-icon.jpg"}, {"label": "Logo, landscape", "size": "PNG", "url": "https://vegansexplore.com/public/logo-ve-landscape-v2.png"}, {"label": "Logo, portrait", "size": "PNG", "url": "https://vegansexplore.com/public/logo-ve-portrait-v2.png"}, {"label": "The suitcase mark", "size": "PNG", "url": "https://vegansexplore.com/public/logo-ve-mark.png"}], "mock": "https://vegansexplore.com/mocks/brand-kit/social"}'::jsonb), updated_at = now() where brand_slug = 'vegans-explore';
insert into ve_links (code, label, destination, initiative_slug, tags, channel)
select 've-bio-' || p, 'Vegans Explore ' || n || ' profile link', 'https://vegansexplore.com/?from=' || p || '-bio', 've-social-profiles', array['bio', p], 'social'
from (values ('instagram','Instagram'),('tiktok','TikTok'),('facebook','Facebook'),('youtube','YouTube'),('x','X'),('threads','Threads'),('linkedin','LinkedIn')) v(p, n)
where not exists (select 1 from ve_links where code = 've-bio-' || p);
